<script setup lang="ts">
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import InputError from '@/Components/InputError.vue';
import { Head, Link, useForm } from '@inertiajs/vue3';

const props = defineProps<{ event: any; activity: any; fromSetup: boolean }>();
const form = useForm({ title: props.activity?.title || '', activity_type: props.activity?.activity_type || '', description: props.activity?.description || '', start_date: props.activity?.start_date || props.event.main_date || '', start_time: props.activity?.start_time || '', end_date: props.activity?.end_date || '', end_time: props.activity?.end_time || '', venue: props.activity?.venue || '', address: props.activity?.address || '', location_url: props.activity?.location_url || '', location_notes: props.activity?.location_notes || '', display_order: props.activity?.display_order || 0, from_setup: props.fromSetup });
const submit = () => props.activity ? form.put(route('events.activities.update', [props.event.id, props.activity.id])) : form.post(route('events.activities.store', props.event.id));
</script>

<template>
    <Head :title="activity ? 'Edit Activity' : 'Add Activity'" />
    <AuthenticatedLayout><template #header><div class="flex justify-between"><div><h2 class="text-xl font-semibold">{{ activity ? 'Edit Activity' : 'Add Activity' }}</h2><p class="text-sm text-gray-600">Times shown in {{ event.event_timezone }}</p></div><Link :href="fromSetup ? route('events.setup',{event:event.id,step:3}) : route('events.activities.index', event.id)" class="rounded border px-3 py-2 text-sm">{{ fromSetup ? 'Back to Invitation Setup' : 'Back to Schedule' }}</Link></div></template>
        <form class="mx-auto max-w-4xl space-y-5 p-6" @submit.prevent="submit"><section class="grid gap-4 rounded bg-white p-6 shadow sm:grid-cols-2"><div><label class="block text-sm font-medium">Activity title</label><input v-model="form.title" required class="mt-1 w-full rounded border-gray-300"><InputError :message="form.errors.title" class="mt-1" /></div><div><label class="block text-sm font-medium">Category / type</label><input v-model="form.activity_type" placeholder="Ceremony, Reception, Custom…" class="mt-1 w-full rounded border-gray-300"><InputError :message="form.errors.activity_type" class="mt-1" /></div><div class="sm:col-span-2"><label class="block text-sm font-medium">Description</label><textarea v-model="form.description" class="mt-1 w-full rounded border-gray-300" /></div></section><section class="grid gap-4 rounded bg-white p-6 shadow sm:grid-cols-2"><h3 class="sm:col-span-2 text-lg font-semibold">Schedule <span class="text-sm font-normal text-gray-500">({{ event.event_timezone }})</span></h3><div><label class="block text-sm font-medium">Start date</label><input v-model="form.start_date" type="date" required class="mt-1 w-full rounded border-gray-300"><InputError :message="form.errors.start_date" class="mt-1" /></div><div><label class="block text-sm font-medium">Start time</label><input v-model="form.start_time" type="time" required class="mt-1 w-full rounded border-gray-300"><InputError :message="form.errors.start_time" class="mt-1" /></div><div><label class="block text-sm font-medium">End date</label><input v-model="form.end_date" type="date" class="mt-1 w-full rounded border-gray-300"><InputError :message="form.errors.end_date" class="mt-1" /></div><div><label class="block text-sm font-medium">End time</label><input v-model="form.end_time" type="time" class="mt-1 w-full rounded border-gray-300"><InputError :message="form.errors.end_time" class="mt-1" /></div></section><section class="grid gap-4 rounded bg-white p-6 shadow sm:grid-cols-2"><h3 class="sm:col-span-2 text-lg font-semibold">Location</h3><div><label class="block text-sm font-medium">Venue</label><input v-model="form.venue" class="mt-1 w-full rounded border-gray-300"></div><div><label class="block text-sm font-medium">Address</label><input v-model="form.address" class="mt-1 w-full rounded border-gray-300"></div><div class="sm:col-span-2"><label class="block text-sm font-medium">Maps / location URL</label><input v-model="form.location_url" type="url" class="mt-1 w-full rounded border-gray-300"><InputError :message="form.errors.location_url" class="mt-1" /></div><div class="sm:col-span-2"><label class="block text-sm font-medium">Location / arrival notes</label><textarea v-model="form.location_notes" class="mt-1 w-full rounded border-gray-300" /></div><div><label class="block text-sm font-medium">Display order</label><input v-model="form.display_order" type="number" min="0" class="mt-1 w-full rounded border-gray-300"><InputError :message="form.errors.display_order" class="mt-1" /></div></section><button :disabled="form.processing" class="rounded bg-indigo-600 px-4 py-2 text-white">{{ activity ? 'Save Activity' : 'Add Activity' }}</button></form>
    </AuthenticatedLayout>
</template>
